import{_ as d,C as o,o as i,c as l,a0 as a,E as s,w as t,b as c,a1 as u,j as h}from"./chunks/framework.C5ukcOJf.js";const C=JSON.parse('{"title":"RP-Initiated Logout","description":"","frontmatter":{"prev":{"text":"Authorization Code Flow","link":"/docs/references/authorization_code_flow"},"next":{"text":"Sessions","link":"/docs/concepts/sessions"}},"headers":[],"relativePath":"docs/references/session_logout_flow.md","filePath":"docs/references/session_logout_flow.md"}'),p={name:"docs/references/session_logout_flow.md"};function _(g,e,f,k,m,v){const n=o("Mermaid"),r=o("ClientOnly");return i(),l("div",null,[e[1]||(e[1]=a('<h1 id="rp-initiated-logout" tabindex="-1">RP-Initiated Logout <a class="header-anchor" href="#rp-initiated-logout" aria-label="Permalink to &quot;RP-Initiated Logout&quot;">​</a></h1><p>RP-Initiated Logout is an OpenID Connect extension that lets a <a href="/okta-client-javascript/docs/concepts/oauth2#actors">relying party</a> (the client) end a user&#39;s session at the <a href="/okta-client-javascript/docs/concepts/oauth2#actors">authorization server</a> — as opposed to <a href="/okta-client-javascript/api/auth-foundation/Credential/classes/Credential#revoke"><code>revoke()</code></a>, which only invalidates a specific token. It&#39;s implemented by <a href="/okta-client-javascript/api/oauth2-flows/SessionLogoutFlow"><code>SessionLogoutFlow</code></a> in this SDK.</p><p>The flow works by redirecting the user&#39;s browser to the authorization server&#39;s <code>end_session_endpoint</code>, passing along the ID token being signed out of (as proof of the session to end) and an optional URL to return to once logout completes.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><code>SessionLogoutFlow</code> only builds this redirect URL — it doesn&#39;t revoke any tokens itself. Whether the authorization server&#39;s <code>end_session_endpoint</code> invalidates the underlying tokens server-side is IDP-dependent. To explicitly invalidate a token, use <a href="/okta-client-javascript/api/auth-foundation/Credential/classes/Credential#revoke"><code>Credential.revoke()</code></a> from <code>@okta/auth-foundation</code>.</p></div><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><ul><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Resource Owner</a>:</strong> the user signing out</li><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Relying Party</a>:</strong> your application</li><li><strong><a href="/okta-client-javascript/docs/concepts/oauth2#actors">Authorization Server</a> / <a href="/okta-client-javascript/docs/concepts/oauth2#actors">Identity Provider</a>:</strong> owns the session being terminated</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2>',7)),s(r,null,{default:t(()=>[(i(),c(u,null,{default:t(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20User%20as%20User%20(Browser)%0A%20%20%20%20participant%20Client%0A%20%20%20%20participant%20AS%20as%20Authorization%20Server%0A%0A%20%20%20%20Client-%3E%3EClient%3A%20Generate%20state%2C%20resolve%20id_token_hint%20from%20current%20session%0A%20%20%20%20Client-%3E%3EUser%3A%20Redirect%20to%20end_session_endpoint%20(id_token_hint%2C%20post_logout_redirect_uri%2C%20state)%0A%20%20%20%20User-%3E%3EAS%3A%20GET%20end_session_endpoint%0A%20%20%20%20AS-%3E%3EAS%3A%20Validate%20id_token_hint%2C%20terminate%20IDP%20session%0A%20%20%20%20AS-%3E%3EUser%3A%20Redirect%20to%20post_logout_redirect_uri%20(state)%0A%20%20%20%20User-%3E%3EClient%3A%20Client%20parses%20state%20from%20url%20(post_logout_redirect_uri)%0A%20%20%20%20Client-%3E%3EClient%3A%20Verify%20state%20matches%20original%20request%0A%20%20%20%20Client-%3E%3EClient%3A%20Remove%20local%20credential%20(Credential.remove())%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h("div",{class:"mermaid mermaid--loading","aria-busy":"true","aria-label":"Loading diagram"},null,-1)])]),_:1}))]),_:1}),e[2]||(e[2]=a('<ol><li>The client resolves the ID token for the session being ended and generates a <code>state</code> value.</li><li>The client redirects the user&#39;s browser to the authorization server&#39;s <code>end_session_endpoint</code>, including <code>id_token_hint</code>, <code>post_logout_redirect_uri</code>, and <code>state</code>.</li><li>The authorization server validates the <code>id_token_hint</code> and terminates the session it represents at the IDP.</li><li>The authorization server redirects the browser back to <code>post_logout_redirect_uri</code> with the original <code>state</code>.</li><li>The client verifies the returned <code>state</code> matches what it sent in step 1.</li><li>The client removes its own local credential (see <a href="/okta-client-javascript/docs/guides/Credential#removing">Managing User Credentials</a>), since RP-Initiated Logout only ends the IDP session — it doesn&#39;t clear anything the client itself persisted.</li></ol><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security Considerations&quot;">​</a></h2><ul><li><strong><code>state</code></strong> must be unique per logout request and verified on redirect, the same protection it provides during <a href="/okta-client-javascript/docs/references/authorization_code_flow#security-considerations">Authorization Code Flow</a>.</li><li><strong><code>id_token_hint</code></strong> must be a token previously issued to this client — an authorization server should refuse to end a session on behalf of an arbitrary/unrelated ID token.</li><li><strong><code>post_logout_redirect_uri</code></strong> should be validated by the authorization server against a pre-registered allowlist, the same way <code>redirect_uri</code> is validated during sign-in, to prevent an attacker from redirecting a signed-out user somewhere unexpected.</li><li>Ending the IDP session doesn&#39;t retroactively invalidate tokens already issued for it. If tokens need to stop working immediately, revoke them explicitly with <a href="/okta-client-javascript/api/auth-foundation/Credential/classes/Credential#revoke"><code>Credential.revoke()</code></a> in addition to running this flow.</li><li>It&#39;s recommended to make a <code>POST</code> request to the <code>end_session_endpoint</code> instead of <code>GET</code>. In a <code>GET</code> request, the ID token will be exposed as a query parameter (via <code>id_token_hint</code>). A <code>POST</code> request does not have the same concern since the request body is hidden.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>In <a href="/okta-client-javascript/docs/concepts/oauth2#oauth2-extensions">Single Sign-On</a> scenarios, ending the IDP session may sign the user out of <em>every</em> application sharing that session — not just this one. See <a href="/okta-client-javascript/docs/guides/Credential#use-sessionlogout">Managing User Credentials</a> for guidance on when <code>SessionLogoutFlow</code> is (and isn&#39;t) the right tool.</p></div><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li>Okta Documentation: <a href="https://developer.okta.com/docs/api/openapi/okta-oauth/oauth/tag/OrgAS/#tag/OrgAS/operation/logoutWithPost" target="_blank" rel="noreferrer">API Reference</a></li><li><a href="https://openid.net/specs/openid-connect-rpinitiated-1_0.html" target="_blank" rel="noreferrer">OpenID Connect RP-Initiated Logout 1.0</a></li></ul>',6))])}const w=d(p,[["render",_]]);export{C as __pageData,w as default};
